public class UrlBuilderTest {

    @Test
    public void newUrlBuilder_returnsEmptyStringBuilder() {
        assert (new UrlBuilder(null).q == null);
    }

    @Test
    public void newUrlBuilder_setsProtocolAndPathCorrectly() {
        URL u = new URL("https://example.com");
        UrlBuilder builder = new UrlBuilder(u);
        assertEquals("https", u.getProtocol());
        assertEquals("/", u.getPath());
    }

    @Test
    public void appendKeyVal_addsQueryParameter_toStringBuilder() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(null);
        builder.appendKeyVal(kv);
        assertEquals("?key=value", String.valueOf(builder.q));
    }

    @Test
    public void appendToAscii_addsSpaceAsPlusWhenSpaceIsInUnicodeCharacter() throws UnsupportedEncodingException {
        StringBuilder sb = new StringBuilder();
        appendToAscii("ä", true, sb);
        assertEquals("+", sb.toString());
    }

    @Test
    public void appendToAscii_ignoresSpacesThatAreAlreadyEncoded() throws UnsupportedEncodingException {
        StringBuilder sb = new StringBuilder();
        appendToAscii("%20 ", false, sb);
        assertEquals("%20 ", sb.toString());
    }

    @Test
    public void build_buildsCorrectUrlWithPunnedHostAndNonAsciiPath() throws MalformedURLException, URISyntaxException, UnsupportedEncodingException {
        URL u = new URL("https://example.com/ä", 8080);
